const BOOT_VIDEO = require("./assets/ascendsat.mov");
const BOOT_VIDEO_RATE = 3;

const resolveBootVideoUri = () => {
  if (typeof BOOT_VIDEO === "string") return BOOT_VIDEO;
  return BOOT_VIDEO?.uri || BOOT_VIDEO?.default || "";
};

const SessionBootSplash = ({ onVideoComplete }) => {
  const webVideoRef = useRef(null);
  const completedRef = useRef(false);
  const fireComplete = () => {
    if (completedRef.current) return;
    completedRef.current = true;
    onVideoComplete?.();
  };

  useEffect(() => {
    if (Platform.OS !== "web") return;
    const video = webVideoRef.current;
    if (!video) return;
    video.playbackRate = BOOT_VIDEO_RATE;
    video.play().catch(() => fireComplete());
  }, []);

  const splashWrap = {
    flex: 1,
    backgroundColor: "#ffffff",
    justifyContent: "center",
    alignItems: "center",
    padding: 24,
  };
  const splashVideoBox = {
    width: "100%",
    maxWidth: 320,
    maxHeight: "45%",
    borderRadius: 16,
    overflow: "hidden",
  };
  const splashVideoStyle = {
    width: "100%",
    height: "100%",
    maxHeight: 360,
    objectFit: "contain",
    borderRadius: 16,
  };

  if (Platform.OS === "web") {
    return (
      <View style={splashWrap}>
        <StatusBar barStyle="dark-content" />
        <View style={splashVideoBox}>
          <video
            ref={webVideoRef}
            src={resolveBootVideoUri()}
            autoPlay
            muted
            playsInline
            style={splashVideoStyle}
            onLoadedMetadata={(e) => {
              e.currentTarget.playbackRate = BOOT_VIDEO_RATE;
              e.currentTarget.play().catch(() => fireComplete());
            }}
            onEnded={fireComplete}
            onError={fireComplete}
          />
        </View>
      </View>
    );
  }

  return (
    <View style={splashWrap}>
      <StatusBar barStyle="dark-content" />
      <Video
        source={BOOT_VIDEO}
        rate={BOOT_VIDEO_RATE}
        shouldPlay
        isMuted
        resizeMode={ResizeMode.CONTAIN}
        style={{ width: "100%", maxWidth: 320, height: 360, borderRadius: 16 }}
        onPlaybackStatusUpdate={(status) => {
          if (status.didJustFinish) fireComplete();
        }}
        onError={fireComplete}
      />
    </View>
  );
};

