const formatTime = (secs) => {
  const m = Math.floor(secs / 60)
    .toString()
    .padStart(2, "0");
  const s = (secs % 60).toString().padStart(2, "0");
  return `${m}:${s}`;
};

const daysUntil = (dateStr) => {
  if (!dateStr) return null;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const target = new Date(dateStr);
  target.setHours(0, 0, 0, 0);
  return Math.ceil((target - today) / (1000 * 60 * 60 * 24));
};

const normalizeQuestionType = (value) => {
  const clean = (value || "").trim().toLowerCase();
  if (clean === "used") return "Used";
  if (clean === "new") return "New";
  return "New";
};

/** Map Google Sheet domain labels → in-app canonical domain names */
const SHEET_DOMAIN_ALIASES = {
  "Craft and Structure": "Craft & Structure",
  "Information Ideas": "Information and Ideas",
  "Geometry and Trigonometry": "Geometry & Trigonometry",
};

const normalizeSheetDomain = (domain) => {
  const d = (domain || "").trim();
  return SHEET_DOMAIN_ALIASES[d] || d;
};

const parseQuestionBankTsv = (tsv) => {
  const lines = tsv.trim().split("\n").filter((line) => line.trim());
  if (lines.length < 2) return [];

  const header = lines[0].split("\t").map((h) => h.trim().toLowerCase());
  const col = (name) => header.indexOf(name);
  const domainIdx = col("domain");
  const difficultyIdx = col("difficulty");
  const questionIdx = col("question");
  const passageIdx = col("passage");
  const typeIdx = col("questiontype") >= 0 ? col("questiontype") : col("type");
  const answerIdx = col("answer");
  const explanationIdx = col("explanation");
  const choiceIdx = (letter) => col(letter);

  const useHeader = domainIdx >= 0 && questionIdx >= 0 && answerIdx >= 0;
  const dataRows = lines.slice(1);

  return dataRows
    .map((row) => {
      const cols = row.split("\t");
      const domain = normalizeSheetDomain(useHeader ? cols[domainIdx]?.trim() : cols[0]?.trim());
      const difficulty = (useHeader ? cols[difficultyIdx] : cols[1])?.trim();
      const passage = passageIdx >= 0 ? (cols[passageIdx] || "").trim() : "";
      const question = (useHeader ? cols[questionIdx] : cols[2])?.trim();
      const choices = useHeader
        ? [choiceIdx("a"), choiceIdx("b"), choiceIdx("c"), choiceIdx("d")].map((i) => (i >= 0 ? cols[i]?.trim() : "") || "")
        : [cols[3], cols[4], cols[5], cols[6]].map((c) => c?.trim() || "");
      const answerLetter = (useHeader ? cols[answerIdx] : cols[7])?.trim();
      const answer = ["A", "B", "C", "D"].indexOf(answerLetter);
      const explanation = (useHeader ? cols[explanationIdx] : cols[8])?.trim() || "";
      const questionType = normalizeQuestionType(
        typeIdx >= 0 ? cols[typeIdx]?.trim() : cols[9]?.trim()
      );

      return { domain, difficulty, passage, question, choices, answer, explanation, questionType };
    })
    .filter((q) => q.domain && q.question && q.answer >= 0 && q.choices.every(Boolean));
};
