/* ================================================================
   MODULE-LEVEL SHELL COMPONENTS
   Defined outside App() so their identity is stable across renders.
   Stable identity = no remount on timer ticks = no modal flicker.
   ================================================================ */

const TierModal = ({ isLight, tierModalVisible, setTierModalVisible, userTier, dailyUsage, upgradeToPro, stripeLoading, stripeError }) => {
  const isPro = userTier === "pro";
  const today = new Date().toISOString().split("T")[0];
  const usage = dailyUsage.date === today ? dailyUsage : { questions: 0, quizzes: 0, adaptive: 0, fullTests: 0 };
  const P = isLight ? APP_PALETTE.light : APP_PALETTE.dark;
  const GOLD = accentColorFor(isLight);
  const GOLD_GLOW = accentGlowFor(isLight);
  const cardBg = P.bg1;
  const borderC = P.border0;
  const textMain = P.text0;
  const textSub = P.text1;
  return (
    <Modal visible={tierModalVisible} transparent animationType="fade">
      <View style={{ flex: 1, backgroundColor: "rgba(0,0,0,0.75)", justifyContent: "center", padding: 20 }}>
        <View style={{ backgroundColor: cardBg, borderRadius: 20, padding: 24, borderWidth: 1, borderColor: borderC, overflow: "hidden" }}>
          <View style={{ position: "absolute", top: 0, left: 0, right: 0, height: 3, backgroundColor: GOLD }} />
          <TouchableOpacity onPress={() => setTierModalVisible(false)} style={{ alignSelf: "flex-end", marginBottom: 4 }}>
            <Text style={{ color: textSub, fontSize: 22 }}>✕</Text>
          </TouchableOpacity>
          <View style={{ marginBottom: 20 }}>
            <Text style={{ color: textMain, fontSize: 22, fontWeight: "800", textAlign: "center", fontFamily: displayFont() }}>
              {isPro ? "You're on Pro" : "Unlock unlimited practice"}
            </Text>
            <Text style={{ color: textSub, fontSize: 14, textAlign: "center", marginTop: 8, lineHeight: 20 }}>
              {isPro ? "Unlimited quizzes, tests, and full access." : "Practice as much as you want with Pro."}
            </Text>
          </View>
          {!isPro && (
            <View style={{ backgroundColor: P.bg2, borderRadius: 12, padding: 14, marginBottom: 16, borderWidth: 1, borderColor: borderC }}>
              <Text style={{ color: textSub, fontSize: 11, fontWeight: "700", letterSpacing: 1, marginBottom: 10 }}>TODAY'S USAGE</Text>
              {[
                { label: "Quizzes", used: usage.quizzes, limit: FREE_TIER_LIMITS.quizzesPerDay },
                { label: "Practice Tests", used: usage.fullTests, limit: FREE_TIER_LIMITS.fullTests },
              ].map(({ label, used, limit }) => (
                <View key={label} style={{ flexDirection: "row", justifyContent: "space-between", marginBottom: 6 }}>
                  <Text style={{ color: textMain, fontSize: 13 }}>{label}</Text>
                  <Text style={{ color: used >= limit ? "#dc2626" : textSub, fontWeight: "600", fontSize: 13 }}>{used}/{limit}</Text>
                </View>
              ))}
            </View>
          )}
          {!isPro && (
            <>
              <TouchableOpacity
                style={{ ...goldBtnStyle(stripeLoading, GOLD), padding: 16, alignItems: "center", marginBottom: 8 }}
                onPress={() => { hapticLight(); !stripeLoading && upgradeToPro("monthly"); }}
                disabled={stripeLoading}
              >
                <Text style={{ color: "#0b1020", fontWeight: "800", fontSize: 16 }}>
                  {stripeLoading ? "Connecting to checkout..." : "Unlock Pro — $9.99/mo"}
                </Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={{ backgroundColor: P.bg2, padding: 14, borderRadius: 12, alignItems: "center", marginBottom: 12, borderWidth: 1, borderColor: borderC, opacity: stripeLoading ? 0.7 : 1 }}
                onPress={() => { hapticLight(); !stripeLoading && upgradeToPro("yearly"); }}
                disabled={stripeLoading}
              >
                <Text style={{ color: textMain, fontWeight: "700", fontSize: 15 }}>Annual — $50/year</Text>
              </TouchableOpacity>
            </>
          )}
          {stripeError ? (
            <View style={{ backgroundColor: isLight ? "#fff1f2" : "#1a0808", borderRadius: 10, padding: 12, marginBottom: 14, borderWidth: 1, borderColor: isLight ? "#fecaca" : "#5a1515" }}>
              <Text style={{ color: "#dc2626", fontSize: 13, lineHeight: 20 }}>{stripeError}</Text>
            </View>
          ) : null}
          <TouchableOpacity style={{ backgroundColor: P.bg2, padding: 14, borderRadius: 12, alignItems: "center" }} onPress={() => setTierModalVisible(false)}>
            <Text style={{ color: textSub, fontWeight: "600", fontSize: 14 }}>{isPro ? "Close" : "I'll wait until tomorrow"}</Text>
          </TouchableOpacity>
        </View>
      </View>
    </Modal>
  );
};

