/* ── Draggable / resizable Desmos panel (web + practice overlay) ── */
const DesmosPanel = ({ visible, onClose, isLight }) => {
  const P = isLight ? APP_PALETTE.light : APP_PALETTE.dark;
  const [pos, setPos] = useState({ x: 80, y: 72 });
  const [size, setSize] = useState({ w: 520, h: 420 });
  const dragRef = useRef(null);
  const resizeRef = useRef(null);

  useEffect(() => {
    if (Platform.OS !== "web" || !visible) return;
    const onMove = (e) => {
      if (dragRef.current) {
        setPos({ x: e.clientX - dragRef.current.ox, y: Math.max(0, e.clientY - dragRef.current.oy) });
      }
      if (resizeRef.current) {
        setSize({
          w: Math.max(320, e.clientX - resizeRef.current.sx),
          h: Math.max(280, e.clientY - resizeRef.current.sy),
        });
      }
    };
    const onUp = () => { dragRef.current = null; resizeRef.current = null; };
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
    return () => { window.removeEventListener("mousemove", onMove); window.removeEventListener("mouseup", onUp); };
  }, [visible]);

  if (!visible) return null;
  if (Platform.OS !== "web") {
    return (
      <Modal visible transparent animationType="fade" onRequestClose={onClose}>
        <View style={{ flex: 1, backgroundColor: "rgba(0,0,0,0.6)", justifyContent: "center", padding: 16 }}>
          <View style={{ height: 400, backgroundColor: "#121214", borderRadius: 12, overflow: "hidden", borderWidth: 1, borderColor: "#2a2a30" }}>
            <View style={{ flexDirection: "row", justifyContent: "space-between", padding: 10, backgroundColor: "#1a1a1e" }}>
              <Text style={{ color: "#e8e8ec", fontWeight: "700" }}>📐 Desmos</Text>
              <TouchableOpacity onPress={onClose}><Text style={{ color: "#8a8a95" }}>✕</Text></TouchableOpacity>
            </View>
            <DesmosGraphingCalculator height={352} />
          </View>
        </View>
      </Modal>
    );
  }

  return (
    <div
      style={{
        position: "fixed", left: pos.x, top: pos.y, width: size.w, height: size.h,
        zIndex: 9000, borderRadius: 12, overflow: "hidden",
        border: `1px solid ${P.border0}`,
        boxShadow: "0 8px 32px rgba(0,0,0,0.45)",
        display: "flex", flexDirection: "column", background: "#121214",
        pointerEvents: "auto",
      }}
    >
      <div
        style={{ cursor: "grab", background: "#1a1a1e", padding: "8px 12px", display: "flex", justifyContent: "space-between", alignItems: "center", userSelect: "none", borderBottom: "1px solid #2a2a30" }}
        onMouseDown={(e) => { dragRef.current = { ox: e.clientX - pos.x, oy: e.clientY - pos.y }; }}
      >
        <span style={{ color: "#e8e8ec", fontWeight: 700, fontSize: 13 }}>📐 Desmos Calculator</span>
        <button onClick={onClose} style={{ background: "rgba(255,255,255,0.1)", border: "none", borderRadius: 6, color: "#e8e8ec", padding: "2px 8px", cursor: "pointer", fontWeight: 700 }}>✕</button>
      </div>
      <div style={{ flex: 1, minHeight: 0 }}>
        <DesmosGraphingCalculator height={size.h - 40} />
      </div>
      <div
        style={{ position: "absolute", right: 0, bottom: 0, width: 18, height: 18, cursor: "nwse-resize", background: "rgba(255,255,255,0.08)", borderTopLeftRadius: 6 }}
        onMouseDown={(e) => { e.stopPropagation(); resizeRef.current = { sx: pos.x, sy: pos.y }; }}
      />
    </div>
  );
};

const WebLayout = ({ isLight, userName, userTier, setView, transitionToView, viewTransitionAnim, viewSlideAnim, setDesmosVisible, setTierModalVisible, handleLogout, desmosVisible, activeView, children, onLoadClasses, onLoadTestimonials, onLoadPromotions, onLoadLessons, onOpenGames, onOpenDrills, onOpenStructuralDrills, onOpenFullTest, onOpenFeedback, onOpenDiagnostic, drillsTab, autopilotActive, onEndAutopilot, autopilotLabel, toolUsage, userProfile, scoreHistory, dockMode = "home-only" }) => {
  const P = isLight ? APP_PALETTE.light : APP_PALETTE.dark;
  const GOLD = accentColorFor(isLight);
  const GOLD_GLOW = accentGlowFor(isLight);
  const [studyToolsExpanded, setStudyToolsExpanded] = useState(false);
  const [moreExpanded, setMoreExpanded] = useState(false);
  const [moreSheetVisible, setMoreSheetVisible] = useState(false);
  const navGo = (v) => { if (!autopilotActive) { hapticLight(); (transitionToView || setView)(v); } };
  const navAction = (fn) => { if (!autopilotActive) { hapticLight(); fn?.(); } };

  const NAV_CORE = [
    { id: "home", label: "Home", icon: "home", onPress: () => navGo("home") },
    { id: "practice", label: "Practice", icon: "edit-3", onPress: () => navGo("practice") },
    { id: "fulltest", label: "Full Test", icon: "clipboard", onPress: () => navAction(onOpenFullTest) },
    { id: "smartQuiz", label: "Smart Quiz", icon: "zap", onPress: () => navGo("smartQuiz") },
    { id: "review", label: "Review", icon: "search", onPress: () => navGo("review") },
    { id: "growth", label: "Progress", icon: "trending-up", onPress: () => navGo("growth") },
    { id: "studyPlan", label: "Study Plan", icon: "map", onPress: () => navGo("studyPlan") },
    { id: "promotions", label: "Promotions", icon: "gift", onPress: () => navAction(() => { onLoadPromotions?.(); (transitionToView || setView)("promotions"); }) },
  ];
  const NAV_STUDY = [
    { id: "drills", label: "Drills", icon: "target", onPress: () => navAction(onOpenDrills) },
    { id: "structuralDrills", label: "Structural Drills", icon: "grid", onPress: () => navAction(onOpenStructuralDrills) },
    { id: "lessons", label: "Lessons", icon: "book-open", onPress: () => navAction(onLoadLessons) },
    { id: "games", label: "Games", icon: "layout", onPress: () => navAction(onOpenGames) },
    { id: "vocab", label: "Vocab", icon: "book", onPress: () => navGo("vocab") },
    { id: "desmosLessons", label: "Desmos", icon: "percent", onPress: () => navGo("desmosLessons") },
    { id: "cramsheets", label: "Cram Sheets", icon: "file-text", onPress: () => navGo("cramsheets") },
  ];
  const NAV_MORE = [
    { id: "tools", label: "Tools", icon: "tool", onPress: () => navGo("tools") },
    { id: "extras", label: "Extras", icon: "star", onPress: () => navGo("extras") },
    { id: "classes", label: "Classes", icon: "users", onPress: () => navAction(() => { onLoadClasses?.(); (transitionToView || setView)("classes"); }) },
    { id: "testimonials", label: "Testimonials", icon: "message-circle", onPress: () => navAction(() => { onLoadTestimonials?.(); (transitionToView || setView)("testimonials"); }) },
  ];
  const NAV_SYSTEM = [
    { id: "feedback", label: "Feedback", icon: "message-circle", onPress: () => (onOpenFeedback ? onOpenFeedback() : navGo("feedback")) },
    { id: "settings", label: "Settings", icon: "settings", onPress: () => navGo("settings") },
  ];

  const isActive = (id) => {
    if (id === "home") return activeView === "home";
    if (id === "practice") return activeView === "practice" || activeView === "results";
    if (id === "growth") return activeView === "growth" || activeView === "timeAnalytics";
    if (id === "studyPlan") return activeView === "studyPlan" || activeView === "studyCalendar";
    if (id === "fulltest") return activeView === "fullTest";
    if (id === "smartQuiz") return activeView === "smartQuiz";
    if (id === "desmosLessons") return activeView === "desmosLessons";
    if (id === "structuralDrills") return activeView === "drills" && drillsTab === "concept";
    if (id === "drills") return activeView === "drills" && drillsTab !== "concept";
    return activeView === id;
  };

  const mobileTabActive = (tab) => {
    if (tab === "home") return activeView === "home";
    if (tab === "practice") return activeView === "practice" || activeView === "results";
    if (tab === "growth") return activeView === "growth" || activeView === "timeAnalytics" || activeView === "studyPlan" || activeView === "studyCalendar";
    if (tab === "more") return [...NAV_STUDY, ...NAV_MORE, ...NAV_SYSTEM].some((item) => isActive(item.id));
    return false;
  };

  const dockToolIds = React.useMemo(
    () => getDockToolIds(toolUsage, userProfile, scoreHistory),
    [toolUsage, userProfile, scoreHistory]
  );

  const visibleDockToolIds = React.useMemo(() => {
    if (dockMode === "hidden") return [];
    if (dockMode === "full") return dockToolIds;
    return [PINNED_TOOL_ID];
  }, [dockMode, dockToolIds]);

  const dockToolActive = (toolId) => {
    const navId = toolId === "fullTest" ? "fulltest" : toolId;
    return isActive(navId);
  };

  const handleDockPress = (toolId) => {
    if (autopilotActive) return;
    const handlers = {
      home: () => navGo("home"),
      practice: () => navGo("practice"),
      smartQuiz: () => navGo("smartQuiz"),
      fullTest: () => navAction(onOpenFullTest),
      review: () => navGo("review"),
      growth: () => navGo("growth"),
      drills: () => navAction(onOpenDrills),
      lessons: () => navAction(onLoadLessons),
      games: () => navAction(onOpenGames),
      vocab: () => navGo("vocab"),
      desmosLessons: () => navGo("desmosLessons"),
      cramsheets: () => navGo("cramsheets"),
      studyPlan: () => navGo("studyPlan"),
      weakAreas: () => navGo("weakAreas"),
      diagnostic: () => navAction(onOpenDiagnostic),
      settings: () => navGo("settings"),
    };
    handlers[toolId]?.();
  };

  React.useEffect(() => {
    if (NAV_STUDY.some((item) => isActive(item.id))) setStudyToolsExpanded(true);
    if (NAV_MORE.some((item) => isActive(item.id))) setMoreExpanded(true);
  }, [activeView, drillsTab]);

  React.useEffect(() => {
    injectFrauncesWebFont();
    if (Platform.OS !== "web") return;
    const styleId = "ascend-app-shell-css";
    let styleEl = document.getElementById(styleId);
    if (!styleEl) {
      styleEl = document.createElement("style");
      styleEl.id = styleId;
      document.head.appendChild(styleEl);
    }
    const ringSoft = isLight ? "rgba(200,106,75,0.12)" : "rgba(245,197,24,0.12)";
    const ringStrong = isLight ? "rgba(200,106,75,0.35)" : "rgba(245,197,24,0.35)";
    const pulseA = isLight ? "rgba(200,106,75,0.35)" : "rgba(240,180,41,0.35)";
    const pulseB = isLight ? "rgba(200,106,75,0.55)" : "rgba(240,180,41,0.55)";
    const pulseC = isLight ? "rgba(200,106,75,0.18)" : "rgba(240,180,41,0.18)";
    styleEl.textContent = `
      html, body, #root {
        height: 100% !important;
        min-height: 100% !important;
        max-height: 100% !important;
        overflow: hidden !important;
        margin: 0;
      }
      body { background-color: ${P.bg0}; }
      .ascend-premium-card {
        transition: transform 180ms cubic-bezier(0.16, 1, 0.3, 1), box-shadow 180ms ease, border-color 180ms ease;
      }
      .ascend-premium-card:hover {
        transform: translateY(-2px);
        box-shadow: 0 8px 32px ${ringSoft};
        border-color: ${ringStrong} !important;
      }
      .ascend-nav-item {
        transition: transform 150ms ease, background-color 150ms ease;
      }
      .ascend-nav-item:hover {
        transform: translateX(2px);
      }
      @keyframes conversionPulse { 0%, 100% { box-shadow: 0 10px 34px ${pulseA}; } 50% { box-shadow: 0 10px 34px ${pulseB}, 0 0 22px 6px ${pulseC}; } }
      .ascend-gold-cta-pulse { animation: conversionPulse 3s ease-in-out infinite; }
      .ascend-home-rail-sticky { position: sticky; top: 20px; align-self: flex-start; }
      .ascend-suggestion-row { transition: background-color 150ms ease; border-radius: 10px; }
      .ascend-suggestion-row:hover { background-color: ${isLight ? "rgba(200,106,75,0.06)" : "rgba(245,197,24,0.06)"}; }
    `;
    return () => { styleEl?.remove(); };
  }, [P.bg0, isLight]);

  const renderNavItem = (item, nested = false) => {
    const active = isActive(item.id);
    return (
      <TouchableOpacity key={item.id} onPress={item.onPress} {...(Platform.OS === "web" ? { className: "ascend-nav-item" } : {})} style={{ flexDirection: "row", alignItems: "center", paddingLeft: nested ? 20 : 12, paddingRight: 12, paddingVertical: 8, marginHorizontal: 8, marginBottom: 2, borderRadius: 8, backgroundColor: active ? GOLD + "22" : "transparent", position: "relative" }}>
        {active && (
          <View style={{ position: "absolute", left: 0, top: "20%", bottom: "20%", width: 3, borderRadius: 2, backgroundColor: GOLD }} />
        )}
        <NavIcon name={item.icon} color={active ? GOLD : P.text2} />
        <Text style={{ color: active ? GOLD : P.text1, fontSize: 13, fontWeight: active ? "700" : "400" }}>{item.label}</Text>
      </TouchableOpacity>
    );
  };

  const renderSectionLabel = (label) => (
    <Text style={{ color: P.text2, fontSize: 10, fontWeight: "700", letterSpacing: 1.4, paddingHorizontal: 16, paddingTop: 14, paddingBottom: 5 }}>
      {label}
    </Text>
  );

  const renderSectionHeader = (label, expanded, onToggle) => (
    <TouchableOpacity
      onPress={onToggle}
      accessibilityLabel={expanded ? `Collapse ${label}` : `Expand ${label}`}
      style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", paddingHorizontal: 16, paddingTop: 14, paddingBottom: 5 }}
    >
      <Text style={{ color: P.text2, fontSize: 10, fontWeight: "700", letterSpacing: 1.4 }}>{label}</Text>
      <AppIcon name={expanded ? "chevron-down" : "chevron-right"} size={14} color={P.text2} />
    </TouchableOpacity>
  );

  const renderAutopilotBanner = () => autopilotActive ? (
    <View style={{ backgroundColor: "#1a3a5c", paddingHorizontal: 14, paddingVertical: 10, flexDirection: "row", alignItems: "center", gap: 10, borderBottomWidth: 1, borderBottomColor: "#2a5080" }}>
      <NavIcon name="zap" color={GOLD} />
      <View style={{ flex: 1 }}>
        <Text style={{ color: "#fff", fontWeight: "800", fontSize: 13 }}>Autopilot Session</Text>
        <Text style={{ color: "#9ab4d4", fontSize: 11, marginTop: 1 }} numberOfLines={1}>{autopilotLabel || "Adapting your next activity…"}</Text>
      </View>
      <TouchableOpacity onPress={onEndAutopilot} style={{ backgroundColor: "rgba(255,255,255,0.12)", paddingHorizontal: 12, paddingVertical: 6, borderRadius: 8 }}>
        <Text style={{ color: "#fff", fontWeight: "700", fontSize: 12 }}>End Session</Text>
      </TouchableOpacity>
    </View>
  ) : null;

  const slideY = viewSlideAnim ? viewSlideAnim.interpolate({ inputRange: [0, 1], outputRange: [12, 0] }) : 0;
  const contentWrap = (
    <Animated.View style={{ flex: 1, minHeight: 0, opacity: viewTransitionAnim, transform: [{ translateY: slideY }] }}>
      {children}
    </Animated.View>
  );

  const MOBILE_TABS = [
    { id: "home", label: "Home", icon: "home", onPress: () => { setMoreSheetVisible(false); navGo("home"); } },
    { id: "practice", label: "Practice", icon: "edit-3", onPress: () => { setMoreSheetVisible(false); navGo("practice"); } },
    { id: "growth", label: "Progress", icon: "trending-up", onPress: () => { setMoreSheetVisible(false); navGo("growth"); } },
    { id: "more", label: "More", icon: "menu", onPress: () => { hapticLight(); setMoreSheetVisible(true); } },
  ];

  if (Platform.OS !== "web") {
    return (
      <View style={{ flex: 1, backgroundColor: P.bg0 }}>
        {renderAutopilotBanner()}
        <View style={{ flex: 1, paddingBottom: MOBILE_TAB_H }}>
          {contentWrap}
        </View>
        <View style={{ position: "absolute", bottom: 0, left: 0, right: 0, height: MOBILE_TAB_H, backgroundColor: P.bg1, borderTopWidth: 1, borderTopColor: P.border0, flexDirection: "row", alignItems: "center", paddingBottom: Platform.OS === "ios" ? 4 : 0 }}>
          {MOBILE_TABS.map((tab) => {
            const active = tab.id === "more" ? moreSheetVisible || mobileTabActive("more") : mobileTabActive(tab.id);
            return (
              <TouchableOpacity key={tab.id} onPress={tab.onPress} style={{ flex: 1, alignItems: "center", justifyContent: "center", paddingVertical: 6 }}>
                <AppIcon name={tab.icon} size={20} color={active ? GOLD : P.text2} />
                <Text style={{ color: active ? GOLD : P.text2, fontSize: 10, fontWeight: active ? "700" : "500", marginTop: 2 }}>{tab.label}</Text>
              </TouchableOpacity>
            );
          })}
        </View>
        <Modal visible={moreSheetVisible} transparent animationType="slide" onRequestClose={() => setMoreSheetVisible(false)}>
          <TouchableOpacity style={{ flex: 1, backgroundColor: "rgba(0,0,0,0.6)" }} activeOpacity={1} onPress={() => setMoreSheetVisible(false)} />
          <View style={{ backgroundColor: P.bg1, borderTopLeftRadius: 20, borderTopRightRadius: 20, paddingTop: 16, paddingBottom: 32, maxHeight: "70%" }}>
            <View style={{ width: 36, height: 4, backgroundColor: P.border0, borderRadius: 2, alignSelf: "center", marginBottom: 16 }} />
            <ScrollView showsVerticalScrollIndicator={false}>
              {renderSectionLabel("STUDY TOOLS")}
              {NAV_STUDY.map((item) => renderNavItem(item))}
              {renderSectionLabel("MORE")}
              {NAV_MORE.map((item) => renderNavItem(item))}
              {renderSectionLabel("SYSTEM")}
              {NAV_SYSTEM.map((item) => renderNavItem(item))}
              <TouchableOpacity onPress={() => { setMoreSheetVisible(false); setTierModalVisible(true); }} style={{ flexDirection: "row", alignItems: "center", paddingHorizontal: 20, paddingVertical: 12, marginTop: 8 }}>
                <NavIcon name="arrow-up" color={userTier === "pro" ? GOLD : P.text2} />
                <Text style={{ color: userTier === "pro" ? GOLD : P.text1, fontSize: 14, fontWeight: "600" }}>{userTier === "pro" ? "Pro Plan" : "Plan / Upgrade"}</Text>
              </TouchableOpacity>
              <TouchableOpacity onPress={() => { setMoreSheetVisible(false); handleLogout(); }} style={{ flexDirection: "row", alignItems: "center", paddingHorizontal: 20, paddingVertical: 12 }}>
                <NavIcon name="log-out" color={P.text2} />
                <Text style={{ color: P.text1, fontSize: 14 }}>Log Out</Text>
              </TouchableOpacity>
            </ScrollView>
          </View>
        </Modal>
      </View>
    );
  }

  return (
    <View style={{ flexDirection: "row", flex: 1, height: "100vh", width: "100%", overflow: "hidden" }}>
      <View style={{
        width: SIDEBAR_W,
        backgroundColor: P.bg1,
        borderRightWidth: 1,
        borderRightColor: "rgba(245,197,24,0.08)",
        paddingTop: 20,
        position: "fixed",
        top: 0,
        left: 0,
        height: "100vh",
        zIndex: 100,
        flexDirection: "column",
      }}>
        <TouchableOpacity onPress={() => navGo("home")} style={{ paddingHorizontal: 16, marginBottom: 16, flexDirection: "row", alignItems: "center", gap: 8 }}>
          <Image source={require("./logo.png")} style={{ width: 28, height: 28, borderRadius: 6 }} resizeMode="contain" />
          <Text style={{ color: P.text0, fontSize: 15, fontWeight: "800", letterSpacing: -0.3 }}>
            Ascend<Text style={{ color: GOLD }}>SAT</Text>
          </Text>
        </TouchableOpacity>
        <ScrollView showsVerticalScrollIndicator={false} style={{ flex: 1, minHeight: 0 }}>
          {renderSectionLabel("CORE")}
          {NAV_CORE.map((item) => renderNavItem(item))}
          {renderSectionHeader("STUDY TOOLS", studyToolsExpanded, () => setStudyToolsExpanded((e) => !e))}
          {studyToolsExpanded && NAV_STUDY.map((item) => renderNavItem(item, true))}
          {renderSectionHeader("MORE", moreExpanded, () => setMoreExpanded((e) => !e))}
          {moreExpanded && NAV_MORE.map((item) => renderNavItem(item, true))}
          {renderSectionLabel("SYSTEM")}
          {NAV_SYSTEM.map((item) => renderNavItem(item))}
        </ScrollView>
        <View style={{ borderTopWidth: 1, borderTopColor: P.border0, paddingTop: 8, paddingBottom: 12 }}>
          <TouchableOpacity onPress={() => setTierModalVisible(true)} style={{ flexDirection: "row", alignItems: "center", paddingHorizontal: 12, paddingVertical: 8, marginHorizontal: 8, marginBottom: 2, borderRadius: 8 }}>
            <NavIcon name="arrow-up" color={userTier === "pro" ? GOLD : P.text2} />
            {userTier === "pro" ? (
              <View style={{ flexDirection: "row", alignItems: "center", gap: 6 }}>
                <Text style={{ color: GOLD, fontSize: 13, fontWeight: "600" }}>Pro Plan</Text>
                <View style={{ backgroundColor: GOLD, paddingHorizontal: 6, paddingVertical: 2, borderRadius: 6 }}>
                  <Text style={{ color: "#0b1020", fontSize: 9, fontWeight: "800" }}>PRO</Text>
                </View>
              </View>
            ) : (
              <Text style={{ color: P.text1, fontSize: 13, fontWeight: "600" }}>Plan / Upgrade</Text>
            )}
          </TouchableOpacity>
          <TouchableOpacity onPress={handleLogout} style={{ flexDirection: "row", alignItems: "center", paddingHorizontal: 12, paddingVertical: 8, marginHorizontal: 8, marginBottom: 2, borderRadius: 8 }}>
            <NavIcon name="log-out" color={P.text2} />
            <Text style={{ color: P.text1, fontSize: 13 }}>Log Out</Text>
          </TouchableOpacity>
          {userName ? (
            <Text style={{ color: P.text2, fontSize: 11, paddingHorizontal: 20, paddingTop: 8 }} numberOfLines={1}>{userName}</Text>
          ) : null}
        </View>
      </View>
      <View style={{ flex: 1, marginLeft: SIDEBAR_W, height: "100vh", overflow: "hidden", position: "relative", minWidth: 0 }}>
        {renderAutopilotBanner()}
        {contentWrap}
        <DesmosPanel visible={desmosVisible} onClose={() => setDesmosVisible(false)} isLight={isLight} />
        <AscendDock
          toolIds={visibleDockToolIds}
          isLight={isLight}
          isItemActive={dockToolActive}
          onItemPress={handleDockPress}
          hidden={autopilotActive || dockMode === "hidden"}
        />
      </View>
    </View>
  );
};

