        practice: "/quiz",
        history: "/history",
        growth: "/growth",
        classes: "/classes",
        settings: "/settings",
        help: "/help",
        feedback: "/feedback",
        results: "/quiz/results",
        timeAnalytics: "/analytics",
        drills: "/drills",
        lessons: "/lessons",
        desmosLessons: "/desmos-lessons",
        games: "/games",
        diagnostic: "/diagnostic",
        vocab: "/vocab",
        review: "/review",
        testimonials: "/testimonials",
        cramsheets: "/cram-sheets",
        fullTest: "/full-test",
        smartQuiz: "/smart-quiz",
