                const r = svg.getBoundingClientRect();
                const x = ((e.clientX - r.left) / r.width) * 520;
                const i = pts.reduce((b, p, j2) => (Math.abs(p[0] - x) < Math.abs(pts[b][0] - x) ? j2 : b), 0);
                cur.setAttribute("transform", `translate(${pts[i][0]},${pts[i][1]})`);
                cur.style.opacity = "1";
                cur.querySelector(".pj-score").textContent = scores[i];
